operations.replacement_region_source:
let input = (*ctxt).input;
let cur_ptr = (*input).cur;
if *cur_ptr as c_int == '\n' as i32 {
    (*input).line += 1;
    (*input).col = 1 as c_int;
} else {
    (*input).col += 1;
}
(*ctxt).token = 0 as c_int;
(*input).cur = cur_ptr.offset(l as isize);
if nbchar >= HTML_PARSER_BIG_BUFFER_SIZE {
    buf[nbchar as usize] = 0 as xmlChar;
    if !(*ctxt).sax.is_null() && (*ctxt).disableSAX == 0 {
        if areBlanks(ctxt, &raw mut buf as *mut xmlChar, nbchar) != 0 {
            if (*ctxt).keepBlanks != 0 {
                if (*(*ctxt).sax).characters.is_some() {
                    (*(*ctxt).sax)
                        .characters
                        .expect("non-null function pointer")(
                        (*ctxt).userData,
                        &raw mut buf as *mut xmlChar,
                        nbchar,
                    );
                }
            } else if (*(*ctxt).sax).ignorableWhitespace.is_some() {
                (*(*ctxt).sax)
                    .ignorableWhitespace
                    .expect("non-null function pointer")(
                    (*ctxt).userData,
                    &raw mut buf as *mut xmlChar,
                    nbchar,
                );
            }
        } else {
            htmlCheckParagraph(ctxt);
            if (*(*ctxt).sax).characters.is_some() {
                (*(*ctxt).sax)
                    .characters
                    .expect("non-null function pointer")(
                    (*ctxt).userData,
                    &raw mut buf as *mut xmlChar,
                    nbchar,
                );
            }
        }
    }
    nbchar = 0 as c_int;
    let input = (*ctxt).input;
    let cur_ptr = (*input).cur;
    if cur_ptr.offset_from((*input).base) as c_long > (2 as c_int * INPUT_CHUNK) as c_long
        && ((*input).end.offset_from(cur_ptr) as c_long) < (2 as c_int * INPUT_CHUNK) as c_long
    {
        xmlParserShrink(ctxt as xmlParserCtxtPtr);
    }
}
cur = htmlCurrentChar(ctxt as xmlParserCtxtPtr, &raw mut l);

